import { LRUCache } from "./lru.js";

// deterministic PRNG (mulberry32, seed 42) for the stress test
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// naive reference LRU: array of [key, value]; index 0 = LRU, last = MRU
class RefLRU {
  constructor(capacity) { this.cap = capacity; this.items = []; }
  get(key) {
    const i = this.items.findIndex(([k]) => k === key);
    if (i === -1) return -1;
    const e = this.items.splice(i, 1)[0];
    this.items.push(e);
    return e[1];
  }
  put(key, value) {
    const i = this.items.findIndex(([k]) => k === key);
    if (i !== -1) this.items.splice(i, 1);
    this.items.push([key, value]);
    if (this.items.length > this.cap) this.items.shift();
  }
}

// --- capacity 2: eviction order with interleaved gets ---
{
  const c = new LRUCache(2);
  c.put(1, 1);
  c.put(2, 2);
  assert.equal(c.get(1), 1);       // 1 becomes MRU
  c.put(3, 3);                     // evicts 2 (LRU)
  assert.equal(c.get(2), -1, "key 2 should have been evicted");
  assert.equal(c.get(3), 3);
  c.put(4, 4);                     // evicts 1
  assert.equal(c.get(1), -1, "key 1 should have been evicted");
  assert.equal(c.get(3), 3);
  assert.equal(c.get(4), 4);
}

// --- get refreshes recency: without the get, the OTHER key is evicted ---
{
  const c = new LRUCache(2);
  c.put("a", 1);
  c.put("b", 2);
  c.get("a");                      // a is MRU now
  c.put("c", 3);                   // evicts b
  assert.equal(c.get("b"), -1, "b (LRU) should have been evicted");
  assert.equal(c.get("a"), 1);
  assert.equal(c.get("c"), 3);
