// FakeStore: writes are deferred onto the microtask queue and reads are
// asynchronous (the getter hands back a Promise). A plain synchronous
// read-modify-write therefore reads a Promise object and loses updates.
class FakeStore {
  constructor() {
    this._v = 0;
    this.pendingSets = 0;
    this.maxPendingSets = 0;
  }
  get value() {
    // async get: callers must await; a sync read sees a Promise object
    return Promise.resolve(this._v);
  }
  set value(v) {
    this.pendingSets++;
    if (this.pendingSets > this.maxPendingSets) this.maxPendingSets = this.pendingSets;
    queueMicrotask(() => {
      this.pendingSets--;
      this._v = v;
    });
  }
}

